mapper.sql:
where oi.delete_flag = 0
 and oi.order_no = #{orderNo}
 and oi.user_id = #{userId}
 and oi.status = #{status}
 and oi.payment_type = #{paymentType}
 and oi.receive_name like concat('%', #{receiveName}, '%')
 and oi.receive_phone = #{receivePhone}
 and date(oi.create_time) = date(#{createTime})

    and exists (
        select 1
        from order_detail od
        inner join product p on p.product_id = od.product_id and p.delete_flag = 0
        where od.order_no = oi.order_no
          and od.delete_flag = 0
          and p.shop_id = #{shopId}
    )
    and not exists (
        select 1
        from order_detail od
        left join product p on p.product_id = od.product_id and p.delete_flag = 0
        where od.order_no = oi.order_no
          and od.delete_flag = 0
          and (p.product_id is null or p.shop_id <> #{shopId})
    )

mapper.select:
select oi.id, oi.order_no, oi.user_id, oi.status
from order_info oi
where oi.id = #{orderId}
  and oi.user_id = #{userId}
  and oi.delete_flag = 0
  and exists (
      select 1
      from order_detail od
      where od.order_no = oi.order_no
        and od.product_id = #{productId}
        and od.delete_flag = 0
  )
for update

select oi.id, oi.order_no, oi.user_id, oi.status
from order_info oi
where oi.order_no = #{orderNo}
  and oi.user_id = #{userId}
  and oi.delete_flag = 0
for update


where oi.user_id = #{userId} and oi.delete_flag = 0
 and oi.status = #{status}
order by oi.create_time desc

mapper.update:
update order_info
set delete_flag = 1, update_time = now()
where id = #{id}
  and user_id = #{userId}
  and delete_flag = 0
  and status in (10, 50, 60)

mapper.select:
select count(*) as total_count, sum(case when status = 10 then 1 else 0 end) as wait_pay_count, sum(case when status = 20 then 1 else 0 end) as wait_ship_count, sum(case when status = 30 then 1 else 0 end) as wait_receive_count, sum(case when status = 40 then 1 else 0 end) as wait_review_count, sum(case when status = 50 then 1 else 0 end) as completed_count, sum(case when status = 60 then 1 else 0 end) as cancelled_count, sum(payment) as total_amount, sum(case when status in (20,30,40,50) then payment else 0 end) as valid_amount from order_info where delete_flag = 0
and create_time >= #{startTime}
and create_time <= #{endTime}
and user_id = #{userId}

select date(create_time) as date, count(*) as order_count, sum(payment) as order_amount from order_info where delete_flag = 0 and status != 60
and create_time >= #{startTime}
and create_time <= #{endTime}
and user_id = #{userId}
group by date(create_time) order by date(create_time) desc
